class Loggers(object):
    def __init__(self, log_id, typeflog, filename=None):
        self.log_id = log_id
        self.typeflog = typeflog
        self.filename = filename
        if self.typeflog == Numbers.BACK:
            self.backtest_path = self.getPath('backtest')
            self.quote_bt_path = self.getPath('quote_bt')
            self.backtest = Backtest(log_id, self.backtest_path, self.filename)
            self.quote = Quote(log_id, self.quote_bt_path, self.filename)
            return None
        elif self.typeflog == Numbers.TRADE:
            self.trade_normal_path = self.getPath('trade_normal')
            self.trade_split_path = self.getPath('trade_split')
            self.quote_tr_path = self.getPath('quote_tr')
            self.trade_norm = Trade_normal(log_id, self.trade_normal_path, self.filename)
            self.trade_split = Trade_split(log_id, self.trade_split_path, self.filename)
            self.quote = Quote(log_id, self.quote_tr_path, self.filename)
            return None
        elif self.typeflog == Numbers.JUPYTER:
            self.jupyterhub_path = self.getPath('jupyterhub')
            self.jupyterhub = Jupyterhub(log_id, self.jupyterhub_path, self.filename)
            return None
        elif self.typeflog == Numbers.BATCH:
            from flybatch.batch_backtest import work_space
            self.backtest = BatchBacktest(log_id, work_space, self.filename)
            self.quote = Quote(log_id, work_space, self.filename)
            return None
    def getPath(self, typeflog='backtest'):
        path = config.getconfigvalue('logpath', typeflog)
        return path
class SafeFileHandler(logging.FileHandler):
    def __init__(self, filename, mode, encoding=None, delay=0):
        logging.FileHandler.__init__(self, filename, mode, encoding, delay)
        self.mode = mode
        self.encoding = encoding
        self.suffix = '%Y-%m-%d'
        self.suffix_time = ''
    def emit(self, record):
        try:
            if self.check_baseFilename(record):
                self.build_baseFilename()
            logging.FileHandler.emit(self, record)
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException:
            self.handleError(record)
            return None
    def check_baseFilename(self, record):
        timeTuple = time.localtime()
        if not self.suffix_time != time.strftime(self.suffix, timeTuple):
            if not os.path.exists(self.baseFilename + '.' + self.suffix_time):
                return 1
            else:
                return 0
    def build_baseFilename(self):
        if self.stream:
            self.stream.close()
            self.stream = None
        if self.suffix_time != '':
            index = self.baseFilename.find('.' + self.suffix_time)
            if index == -1:
                index = self.baseFilename.rfind('.')
            self.baseFilename = self.baseFilename[:index]
        currentTimeTuple = time.localtime()
        self.suffix_time = time.strftime(self.suffix, currentTimeTuple)
        self.baseFilename = self.baseFilename + '.' + self.suffix_time
        self.mode = 'a'
        if not self.delay:
            self.stream = self._open()
            return None
def getLogger(ids, sence, filename=None):
    if dicts.get((ids, filename)):
        return dicts.get((ids, filename))
    else:
        log = Loggers(ids, sence, filename)
        dicts[ids, filename] = log
        return log
